import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import { apiGet } from "utils/api";  // Importujeme naši funkci apiGet

const InvoiceTable = ({ label, items, deleteInvoice, invoicesCount }) => {
    const itemsPerPage = 10;  // Počet položek na stránce
    const totalPages = Math.ceil(invoicesCount / itemsPerPage);  // Celkový počet stránek
    const [currentPage, setCurrentPage] = useState(0);  // Aktuální stránka
    const [invoiceItems, setInvoiceItems] = useState(items);  // Uložení položek faktur pro aktuální stránku

    const handlePageChange = (page) => {
        setCurrentPage(page);
    };

    // Načítání položek pro danou stránku
    useEffect(() => {
        // Načteme položky pro danou stránku z API
        const fetchInvoices = async () => {
            try {
                const params = {
                    page: currentPage,
                    size: itemsPerPage,
                };

                const response = await apiGet("/api/invoices", params);  // Zde voláme API pro faktury
                setInvoiceItems(response.content);  // Předpokládáme, že odpověď má pole 'content'
            } catch (error) {
                console.error("Error fetching invoices:", error);
            }
        };

        fetchInvoices();  // Spustíme načítání dat při změně stránky
    }, [currentPage]);  // Spustí se, když se změní 'currentPage'

    return (
        <div>
            <p>
                {label} {invoiceItems.length} z {invoicesCount} faktur
            </p>

            <table className="table table-bordered">
                <thead>
                    <tr>
                        <th>#</th>
                        <th>Číslo faktury</th>
                        <th>Produkt</th>
                        <th>Popis</th>
                        <th>Cena</th>
                        <th>Koupil</th>
                        <th>Prodal</th>
                        <th>Datum vydání</th>
                        <th>Datum splatnosti</th>
                        <th colSpan={3}>Akce</th>
                    </tr>
                </thead>
                <tbody>
                    {invoiceItems.map((item, index) => (
                        <tr key={index + 1}>
                            <td>{index + 1}</td>
                            <td>{item.invoiceNumber}</td>
                            <td>{item.product}</td>
                            <td>{item.note}</td>
                            <td>{item.price}</td>
                            <td><a href={`persons/show/${item.buyer._id}`}>{item.buyer.name}</a></td>
                            <td><a href={`persons/show/${item.seller._id}`}>{item.seller.name}</a></td>
                            <td>{item.issued}</td>
                            <td>{item.dueDate}</td>
                            <td>
                                <div className="btn-group">
                                    <Link
                                        to={"/invoices/show/" + item._id}
                                        className="btn btn-sm btn-info"
                                    >
                                        Zobrazit
                                    </Link>
                                    <Link
                                        to={"/invoices/edit/" + item._id}
                                        className="btn btn-sm btn-warning"
                                    >
                                        Upravit
                                    </Link>
                                    <button
                                        onClick={() => deleteInvoice(item._id)}
                                        className="btn btn-sm btn-danger"
                                    >
                                        Odstranit
                                    </button>
                                </div>
                            </td>
                        </tr>
                    ))}
                </tbody>
            </table>
            <div className="pagination">
                {Array.from({ length: totalPages }).map((_, index) => (
                    <button
                        key={index}
                        onClick={() => handlePageChange(index)}
                        className={`btn btn-sm ${currentPage === index ? 'btn-primary' : 'btn-secondary'}`}
                    >
                        {index + 1}
                    </button>
                ))}
            </div>
            <Link to={"/invoices/create"} className="btn btn-success">
                Nová faktura
            </Link>
        </div>
    );
};

export default InvoiceTable;
